"""`.eyeline sticker`: generated by export_nodes.py from face_cards.blend; kept by hand from then on."""

NAME = '.eyeline sticker'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Shader', 'NodeSocketShader')
    t.socket('INPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))
    t.socket('INPUT', 'Alpha', 'NodeSocketFloat')
    t.socket('INPUT', 'Color', 'NodeSocketColor', default_value=(0.8, 0.8, 0.8, 1.0))

    t.node('ShaderNodeEmission', 'Emission', props={
        'location': (1080.0, 80.0),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', props={
        'location': (1080.0, 280.0),
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', props={
        'location': (1330.0, 200.0),
    })
    t.node('ShaderNodeMath', 'Math', inputs={'Value': 1.0}, props={
        'location': (-1320.0, -300.0),
        'label': '1 - down alpha',
        'operation': 'SUBTRACT',
    })
    t.node('ShaderNodeMath', 'Math.001', props={
        'location': (-1140.0, -300.0),
        'label': 'prev alpha x (1 - top)',
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.002', props={
        'location': (-960.0, -300.0),
        'label': 'alpha after down',
    })
    t.node('ShaderNodeMath', 'Math.003', props={
        'location': (-780.0, -300.0),
        'label': 'down weight',
        'operation': 'DIVIDE',
    })
    t.node('ShaderNodeMix', 'Mix', props={
        'location': (-600.0, 100.0),
        'label': 'colour after down',
        'data_type': 'RGBA',
    })
    t.node('ShaderNodeMath', 'Math.004', inputs={'Value': 1.0}, props={
        'location': (-420.0, -300.0),
        'label': '1 - up alpha',
        'operation': 'SUBTRACT',
    })
    t.node('ShaderNodeMath', 'Math.005', props={
        'location': (-240.0, -300.0),
        'label': 'prev alpha x (1 - top)',
        'operation': 'MULTIPLY',
    })
    t.node('ShaderNodeMath', 'Math.006', props={
        'location': (-60.0, -300.0),
        'label': 'alpha after up',
    })
    t.node('ShaderNodeMath', 'Math.007', props={
        'location': (120.0, -300.0),
        'label': 'up weight',
        'operation': 'DIVIDE',
    })
    t.node('ShaderNodeMix', 'Mix.001', props={
        'location': (300.0, 100.0),
        'label': 'colour after up',
        'data_type': 'RGBA',
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (1530.0, 0.0),
    })
    t.node('NodeGroupInput', 'Group Input', props={
        'location': (-1520.0, 0.0),
    })

    t.link('Transparent BSDF', 'BSDF', 'Mix Shader', 'Shader')
    t.link('Emission', 'Emission', 'Mix Shader', 'Shader_001')
    t.link('Math', 'Value', 'Math.001', 'Value_001')
    t.link('Math.001', 'Value', 'Math.002', 'Value_001')
    t.link('Math.002', 'Value', 'Math.003', 'Value_001')
    t.link('Math.003', 'Value', 'Mix', 'Factor_Float')
    t.link('Math.002', 'Value', 'Math.005', 'Value')
    t.link('Math.004', 'Value', 'Math.005', 'Value_001')
    t.link('Math.005', 'Value', 'Math.006', 'Value_001')
    t.link('Math.006', 'Value', 'Math.007', 'Value_001')
    t.link('Math.007', 'Value', 'Mix.001', 'Factor_Float')
    t.link('Mix', 'Result_Color', 'Mix.001', 'A_Color')
    t.link('Mix.001', 'Result_Color', 'Emission', 'Color')
    t.link('Math.006', 'Value', 'Mix Shader', 'Fac')
    t.link('Group Input', 4, 'Math.004', 'Value_001')
    t.link('Group Input', 4, 'Math.006', 'Value')
    t.link('Group Input', 4, 'Math.007', 'Value')
    t.link('Group Input', 1, 'Math.001', 'Value')
    t.link('Group Input', 2, 'Mix', 'A_Color')
    t.link('Group Input', 0, 'Math', 'Value_001')
    t.link('Group Input', 0, 'Math.002', 'Value')
    t.link('Group Input', 0, 'Math.003', 'Value')
    t.link('Group Input', 3, 'Mix', 'B_Color')
    t.link('Mix Shader', 'Shader', 'Group Output', 'Shader')
    t.link('Group Input', 5, 'Mix.001', 'B_Color')
    return t
